INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4435, 'koKR', 'Zniewolimy kolcozwierze!', '', 0),
(4436, 'koKR', 'Rozprzestrzenimy się po tej jałowej krainie!', '', 0),
(4437, 'koKR', 'Wkrótce Plaga zapanuje nad światem!', '', 0),
(4493, 'koKR', 'Dobra, trzymaj się blisko. Te bestie wyskoczą na ciebie prosto z cienia, jeśli choć na chwilę stracisz czujność.', '', 0),
(4501, 'koKR', 'No dobrze, zaczynamy. Wygaszenie tego czegoś rytuałem zajmie mniej więcej pięć minut. Kiedy zacznę, trzymaj to robactwo z dala ode mnie, bo inaczej wszyscy zginiemy!', '', 0),
(4504, 'koKR', 'Zostały trzy minuty – czuję, jak energia zaczyna narastać! Tak trzymaj, bronisz się solidnie!', '', 0),
(4505, 'koKR', 'Jeszcze tylko dwie minuty! Jesteśmy w połowie, ale nie trać czujności!', '', 0),
(4506, 'koKR', 'Jeszcze minuta! Wytrzymaj, rytuał zaraz zacznie działać!', '', 0),
(4507, 'koKR', 'Gotowe – udało się! Rytuał ruszył, a ognie idola zaraz zgasną na dobre! Naprawdę jesteście bohaterami, za jakich was uważałem!', '', 0),
(4534, 'koKR', 'Dziękuję za ratunek!$B$BJestem kucharzem i alchemikiem z Wichrogrodu. Szukałem tu miejscowych ziół i przepisów dla mojego wuja Angusa, kiedy złapały mnie te kolcozwierze. Gdyby nie ty, na pewno skończyłbym w ich garnku z gulaszem!', '', 0),
(4535, 'koKR', 'Umiesz gotować? Ja też! Nauczysz mnie jakiegoś przepisu?', 'Umiesz gotować? Ja też! Nauczysz mnie jakiegoś przepisu?', 0),
(4536, 'koKR', 'Hm... tak, mam przepis, który może ci się przydać. Pozwól, że cię nauczę!', '', 0),
(4537, 'koKR', 'Jesteś alchemikiem? Ja też. Może nauczysz mnie tego, co umiesz...', 'Jesteś alchemikiem? Ja też. Może nauczysz mnie tego, co umiesz...', 0),
(4538, 'koKR', 'No tak, znam pewną rzadką recepturę alchemiczną. Pozwól, że cię nauczę!', '', 0),
(4575, 'koKR', 'Jeszcze raz dziękuję, $n. A teraz poczekam tu, aż będzie można bezpiecznie odejść.', '', 0),
(4577, 'koKR', 'Dziękuję ci, $gmaleńki:maleńka;!', '', 0),
(4578, 'koKR', 'Twoje umiejętności kulinarne są odrobinę za niskie. Może po pewnej praktyce będę mógł nauczyć cię tego, co umiem.', '', 0),
(4579, 'koKR', 'Twoje umiejętności alchemiczne nie są jeszcze na tyle wysokie, by moje nauki mogły ci się przydać. Może jeśli porozmawiasz ze mną później...', '', 0),
(6184, 'koKR', 'Zabijcie ich, bracia! Za Plagę!', '', 0),
(6185, 'koKR', 'Ja czuć smród żywych!', '', 0),
(6186, 'koKR', 'Ja pożreć was wszystkich!', '', 0),
(9006, 'koKR', 'Uwaga, $n!', '', 0),
(9008, 'koKR', 'Pożałujesz dnia, w którym $gwszedłeś:weszłaś; mi w drogę, $n.', '', 0),
(12429, 'koKR', 'Dziękuję, że zostajesz moją kolejną ofiarą!', '', 0);
